import subprocess,json
u='prediction-a2z-v4-model@A2Z-V4-ASTRA-PREBUILD-DIRECT-20261007-R4P2.service'
p=subprocess.run(['journalctl','--user','-u',u,'--since','2026-10-07 22:04:30','--until','2026-10-07 22:11:30','--no-pager'],capture_output=True,text=True)
rows=[]
for line in (p.stdout or '').splitlines():
    if 'SUPERVISOR_STATE' in line:
        i=line.find('{')
        if i>=0:
            try:o=json.loads(line[i:])
            except Exception: continue
            cp=str(o.get('checkpoint') or '')
            rows.append(['STATE',o.get('attempt'),o.get('state'),o.get('reason'),cp.rsplit('/',1)[-1],o.get('retry_at')])
    elif 'Started prediction-a2z-v4-model@' in line:
        rows.append(['STARTED'])
    elif 'Main process exited' in line:
        rows.append(['MAIN_EXIT',line.rsplit('status=',1)[-1] if 'status=' in line else ''])
    elif 'Failed with result' in line:
        rows.append(['FAILED_RESULT'])
    elif 'Deactivated successfully' in line:
        rows.append(['DEACTIVATED'])
print('ERROR_CLASS=R4P2_N1E95_ACTUAL_JOURNAL',flush=True)
print('ERROR='+json.dumps(rows,separators=(',',':')),flush=True)
raise SystemExit(1)
